//! Raw `no_std` bindings to the Cortex-A9#0 (`hello_world`) standalone BSP
//! (every header in `artyz7_platform/ps7_cortexa9_0/standalone_ps7_cortexa9_0/bsp/include`), generated by
//! bindgen at build time. Linking this crate pulls in libxil, libxilstandalone, libxiltimer and libxilffs
//! (plus newlib's libc and libgcc) as one link group.
//!
//! Function-like macros (`XTtcPs_Start`, `XWdtPs_RestartWdt`, `dmb`, ...) and
//! `static inline` functions (`Xil_Out32`, ...) are callable under their C names
//! through small C shims compiled alongside the bindings.
#![no_std]
#![allow(non_upper_case_globals, non_camel_case_types, non_snake_case)]
#![allow(clippy::all, rustdoc::all, unnecessary_transmutes)]

include!(concat!(env!("OUT_DIR"), "/bindings.rs"));
